from pathlib import Path
import pandas as pd
F = json.loads(Path("docs/intraday_v3e_fed.json").read_text()); R = json.loads(Path("docs/intraday_v3e_releases.json").read_text()); T = pd.read_csv("processed/fed_release_times.csv", parse_dates=["date"])
g = F["decomposition"]["GC"]; late = T[T["date"] >= "2013-01-01"]; share14 = float((late.t0 == 840).mean())
def best(d):
    b = d.get("best")
