first30 = (g["f5"] + g["m5_30"]) / g["day"]; rest = g["rest"] / g["day"]; p136 = first30 > 0.5 and rest < 0.2; gc = F["catch"]["GC"]; p137 = not (gc["p_family"] < 0.05)
sec = [F["catch"][a]["p_family"] for a in ("ES", "NQ", "ZN")] + [v["p_family"] for v in F.get("score", {}).values() if "p_family" in v] + [R[r][a]["p_family"] for r in ("continuation", "score", "score_disagrees") for a in ("ES", "NQ") if R[r][a].get("best")]
agree = R["first_move_vs_score"]["same_sign"]; p138 = (min(sec) >= 0.005) and (0.50 <= agree <= 0.60); p139 = share14 >= 0.90
